 const employeeRequest=useRef(false),employeeRetryAt=useRef(0),employeeFailures=useRef(0);const [employeeError,setEmployeeError]=useState('');const [employeeRefreshing,setEmployeeRefreshing]=useState(false);async function loadEmployees(force=false){if(employeeRequest.current||(!force&&Date.now()<employeeRetryAt.current))return;employeeRequest.current=true;try{setEmployeeRefreshing(true);const rows=await listEmployees();setEmployees(prev=>JSON.stringify(prev)===JSON.stringify(rows)?prev:rows);setEmployeeError('');employeeFailures.current=0;employeeRetryAt.current=0}catch(e){setEmployeeError(e.message);employeeFailures.current++;employeeRetryAt.current=Date.now()+Math.min(300000,30000*2**employeeFailures.current)}finally{employeeRequest.current=false;setEmployeeRefreshing(false)}}
