 async function saveEmp(allowSimilar=false){if(!emp.name.trim())return setError('Vui lòng nhập họ và tên.');const invalid=validateEmployment(emp);if(invalid)return setError(invalid);if(allowSimilar!==true){const similar=employees.filter(e=>e.id!==emp.id&&employeeSimilarity(emp,e));if(similar.length){askConfirm('Thông tin này giống với nhân viên đã có: '+similar.map(e=>[e.name,e.branch,e.account].filter(Boolean).join(' · ')).join(' | ')+'. Bạn có muốn tiếp tục lưu?',()=>saveEmp(true));return}}try{setLoading(true);const x={...emp,id:emp.id||crypto.randomUUID()};const saved=await upsertEmployee(x);setEmployees(prev=>{const i=prev.findIndex(a=>a.id===saved.id);if(i<0)return [...prev,saved];const n=[...prev];n[i]=saved;return n});setEmpModal(null);flash('Đã lưu thông tin nhân viên.')}catch(e){setError(e.message)}finally{setLoading(false)}}
 async function showImportProgress(phase,label,total=0){setImportProgress({phase,label,total,done:0});await new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,0)))}
