 function reviewImport(rows,kind,audit=rows.importAudit){if(audit&&(audit.skipped.length||audit.warnings?.length)){setImportAudit({rows,kind,...audit});return}const matches=findImportDuplicates(rows,kind==='employees'?employees:attendance,kind);if(matches.length)setImportReview({rows,kind,matches});else commitImport(rows,kind)}
 async function importEmployees(file){try{await showImportProgress('reading','Đang đọc file nhân viên…');setError('');const rows=await parseEmployeeFile(file);reviewImport(rows,'employees')}catch(e){setError(e.message)}finally{setImportProgress(p=>p?.phase==='reading'?null:p);if(employeeFileRef.current)employeeFileRef.current.value=''}}
 async function removeEmployees(ids){askConfirm('Xóa '+ids.length+' nhân viên đã chọn? Các phiếu lương hiện có vẫn được giữ.',async()=>{const removed=[];const failures=[];setLoading(true);for(const id of ids){try{await deleteEmployee(id);removed.push(id)}catch(error){failures.push(error.message)}}setEmployees(prev=>prev.filter(e=>!removed.includes(e.id)));setLoading(false);if(failures.length)setError('Đã xóa '+removed.length+' nhân viên. Một số hồ sơ chưa xóa được: '+failures.join(' | '));else flash('Đã xóa '+removed.length+' nhân viên.')} )}
 async function removeEmp(e){askConfirm(`Xóa ${e.name}?`,async()=>{try{await deleteEmployee(e.id);setEmployees(x=>x.filter(a=>a.id!==e.id));flash('Đã xóa nhân viên.')}catch(err){setError(err.message)}})}
