function clearAttendanceCategory(category){askConfirm(`Xóa chấm công ${category} tại ${attBranch||'Chưa phân chi nhánh'}?`,()=>{setAttendance(prev=>prev.filter(x=>x.category!==category||branchCode(x.branch)!==attBranch));setAttName('');setAttPeriod('all');flash(`Đã xóa toàn bộ chấm công ${category}.`)})}
 function togglePs(id){setSelectedPs(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id])}
 function createPayslips(allowUnmatched=false,leaveValues=null,leaveDetails=null,insuranceChoices={}){
  if(!psEmployeeIds.length)return setModalAlert({title:'Chưa chọn nhân viên',message:'Vui lòng chọn ít nhất một nhân viên trong danh sách bên dưới. Nút “Có chấm công” chỉ dùng để chọn danh sách; phiếu chỉ được khởi tạo khi bạn bấm “Khởi tạo”.',kind:'warning'});
  const dataPeriod=psPeriod||''
  const displayPeriod=psDisplayPeriod||dataPeriod
  const pairOk=(v)=>!v||/^[0-9]{4}-[0-9]{2}$/.test(v)
  if(!dataPeriod && !displayPeriod){setModalAlert({title:'Chọn kỳ hiển thị',message:'Vui lòng nhập kỳ muốn hiển thị trước khi khởi tạo từ nhiều kỳ dữ liệu.',kind:'warning'});return}
  if(!pairOk(dataPeriod)||!pairOk(displayPeriod)){
    setModalAlert({title:'Thời gian chưa đầy đủ',message:'Nếu đã chọn tháng hoặc năm, vui lòng chọn đủ cả tháng và năm. Bạn cũng có thể để trống cả hai nếu không muốn lọc kỳ hoặc không muốn hiển thị thời gian trên phiếu.',kind:'warning'});return
  }
  // “Có chấm công” chỉ chọn danh sách. Nếu có người có chấm công nhưng
  // chưa có hồ sơ nhân viên, chỉ khi bấm Khởi tạo mới hỏi xác nhận.
  if(psAttendanceMode && !allowUnmatched){
    const source=dataPeriod?attendance.filter(x=>x.period===dataPeriod):attendance
    const attendanceNames=new Map()
    for(const row of source){
      const candidates=row.category==='Văn phòng'?[row.employee]:[row.teacher,row.ta]
      for(const raw of candidates){
        const name=String(raw||'').trim();if(!name)continue
        const key=normalizePersonName(name);if(!attendanceNames.has(key))attendanceNames.set(key,name)
      }
    }
    const employeeKeys=new Set(employees.map(e=>normalizePersonName(e.name)))
    const unmatched=[...attendanceNames.entries()].filter(([key])=>!employeeKeys.has(key)).map(([,name])=>name)
    if(unmatched.length){
      const listed=unmatched.slice(0,12).join(', ')+(unmatched.length>12?'…':'')
      askConfirm(`Có ${unmatched.length} người xuất hiện trong dữ liệu chấm công nhưng chưa có thông tin trong danh sách nhân viên: ${listed}.\n\nNếu tiếp tục, web sẽ chỉ khởi tạo phiếu cho những người vừa được chọn và có thông tin nhân viên. Những người thiếu thông tin sẽ được bỏ qua.`,()=>createPayslips(true))
      return
    }
  }
  if(!leaveValues){setLeaveDraft({allowUnmatched,rows:employees.filter(e=>psEmployeeIds.includes(e.id)).map(e=>({id:e.id,name:e.name,compensatory:0,paid:0,unpaid:0}))});return}
  if(leaveDetails===null){const affected=employees.filter(e=>psEmployeeIds.includes(e.id)&&(leaveValues[e.id]?.entered??Object.values(leaveValues[e.id]||{}).some(v=>Number(v)>0)));if(affected.length){setLeaveDraft(null);setLeaveDetailDraft({rows:affected,values:leaveValues,allowUnmatched});return}}
  const made=[],issues=[];
  for(const id of psEmployeeIds){
    const e=employees.find(x=>x.id===id);if(!e)continue;
    if(payslips.some(x=>x.employeeId===id&&x.period===dataPeriod&&!!x.allPeriods===!dataPeriod&&String(x.displayPeriod||'')===displayPeriod)){setError(e.name+': đã có phiếu kỳ này. Dùng Khởi tạo lại để cập nhật tất cả chi nhánh và tránh trừ BH lặp.');return}
    const result=buildBranchPayslips(e,dataPeriod,attendance,{displayPeriod,leaveDays:leaveValues[id],leaveDetails:leaveDetails?.[id]||[],insuranceBranch:insuranceChoices[id]});
    if(result.unassigned){setError(e.name+': có chấm công chưa phân chi nhánh. Vào Chấm công để chuyển các dòng vào đúng chi nhánh trước khi tạo phiếu.');return}
    if(result.needsChoice)issues.push({...result,employee:e});
    for(const p of result.payslips)if(!payslips.some(x=>x.employeeId===id&&x.period===dataPeriod&&!!x.allPeriods===!dataPeriod&&String(x.displayPeriod||'')===displayPeriod&&String(x.branch??'')===p.branch))made.push(p);
  }
  if(issues.length){setInsuranceDraft({issues,onConfirm:choices=>createPayslips(allowUnmatched,leaveValues,leaveDetails||{},choices)});return}
  if(!made.length){setError('Không có dữ liệu để tạo phiếu cho các nhân viên đã chọn.');return}
  setInsuranceDraft(null);setLeaveDetailDraft(null);
  setLeaveDraft(null);setPsSearch('');setPsFilterPeriod(dataPeriod);setPayslips(p=>[...p,...made]);setPsEmployeeIds([]);setPsAttendanceMode(false);setCreateOpen(false);flash(`Đã khởi tạo ${made.length} phiếu.`)
 }
 function selectAllWithAttendance(){
  const dataPeriod=psPeriod||''
  const source=dataPeriod?attendance.filter(x=>x.period===dataPeriod):attendance
  const attendanceKeys=new Set()
  for(const row of source){
    const candidates=row.category==='Văn phòng'?[row.employee]:[row.teacher,row.ta]
    for(const raw of candidates){const name=String(raw||'').trim();if(name)attendanceKeys.add(normalizePersonName(name))}
  }
  const employeeByName=new Map(employees.map(e=>[normalizePersonName(e.name),e]))
  const matchedIds=[]
  for(const key of attendanceKeys){const e=employeeByName.get(key);if(e)matchedIds.push(e.id)}
  for(const e of employees){if(e.noAttendance)matchedIds.push(e.id)}
  const uniqueIds=[...new Set(matchedIds)]
  // Nút “Có chấm công” là nút bật/tắt lựa chọn: lần đầu chọn toàn bộ người có chấm công, lần sau bỏ chọn chính nhóm đó.
  const allAttendanceSelected=uniqueIds.length>0&&uniqueIds.every(id=>psEmployeeIds.includes(id))
  if(allAttendanceSelected){
    setPsEmployeeIds(s=>s.filter(id=>!uniqueIds.includes(id)))
    setPsAttendanceMode(false)
  }else{
    setPsEmployeeIds(s=>[...new Set([...s,...uniqueIds])])
    setPsAttendanceMode(true)
  }
  setPsNameFilter('')
 }
 function recreatePayslips(ids,insuranceChoices={}){
  const requested=payslips.filter(p=>ids.includes(p.id)),groups=new Map(),updates=new Map(),issues=[];
  for(const old of requested){const key=[old.employeeId,old.period,old.displayPeriod,!!old.allPeriods].join('|');if(groups.has(key))continue;groups.set(key,old)}
  for(const old of groups.values()){
    const e=employees.find(x=>x.id===old.employeeId);if(!e)continue;
    const result=buildBranchPayslips(e,old.allPeriods?'':old.period,attendance,{displayPeriod:old.displayPeriod,leaveDays:old.overrides?.leaveDays,leaveDetails:old.overrides?.leaveDetails,insuranceBranch:insuranceChoices[[old.employeeId,old.period,old.displayPeriod,!!old.allPeriods].join('|')]});
    if(result.unassigned)return setError(e.name+': hãy phân chi nhánh cho chấm công trước khi khởi tạo lại.');
    if(result.needsChoice)issues.push({...result,employee:e,choiceKey:[old.employeeId,old.period,old.displayPeriod,!!old.allPeriods].join('|')});
    const siblings=payslips.filter(p=>p.employeeId===old.employeeId&&p.period===old.period&&p.displayPeriod===old.displayPeriod&&!!p.allPeriods===!!old.allPeriods);
    for(const fresh of result.payslips){const previous=siblings.find(p=>String(p.branch??'')===fresh.branch)||(siblings.length===1&&!siblings[0].branch?siblings[0]:null);if(previous){fresh.id=previous.id;fresh.createdAt=previous.createdAt;fresh.overrides.bank=previous.overrides?.bank??fresh.overrides.bank;fresh.overrides.account=previous.overrides?.account??fresh.overrides.account;updates.set(previous.id,fresh)}else updates.set(fresh.id,fresh)}
    for(const previous of siblings)if(![...updates.values()].some(p=>p.id===previous.id))updates.set(previous.id,null);
  }
  if(issues.length){setInsuranceDraft({issues,onConfirm:choices=>recreatePayslips(ids,choices)});return}
  setInsuranceDraft(null);
  if(!updates.size)return setError('Không có phiếu để khởi tạo lại.');
  setPayslips(prev=>[...prev.filter(p=>!updates.has(p.id)),...[...updates.values()].filter(Boolean)]);
  if(viewingPayslip)setViewingPayslip(updates.get(viewingPayslip.id)||null);
  flash('Đã khởi tạo lại '+[...updates.values()].filter(Boolean).length+' phiếu theo chi nhánh; BH chỉ trừ một lần.');
 }

 function recreatePayslip(old){recreatePayslips([old.id])}
