 async function exportOne(p){const e=employees.find(x=>x.id===p.employeeId);if(e)await exportPayslip(p,e,attendance,`PAYSLIP_${e.name}_${periodFileLabel(p.displayPeriod||p.period||'KY')}.xlsx`)}
 function clearSession(){askConfirm(supabase?'Xóa toàn bộ dữ liệu chấm công và phiếu lương trong kho dùng chung? Thay đổi sẽ áp dụng cho mọi thiết bị.':'Xóa toàn bộ dữ liệu chấm công và phiếu lương đang lưu trên trình duyệt?',()=>{localStorage.removeItem('payslip_attendance_v1');localStorage.removeItem('payslip_payslips_v1');sessionStorage.removeItem('payslip_attendance_v1');sessionStorage.removeItem('payslip_payslips_v1');setAttendance([]);setPayslips([]);setSelectedPs([]);setViewingPayslip(null);flash('Đã xóa dữ liệu chấm công và phiếu lương.')})}
 function openAttendanceExport(){const available=[...new Set(attendance.map(r=>branchCode(r.branch)))].sort((a,b)=>a.localeCompare(b,'vi'));if(!available.length)return setError('Chưa có dữ liệu chấm công để xuất.');setAttendanceExport({branches:available,selected:available.includes(attBranch)?[attBranch]:[]})}
 async function exportAttendance(){try{setAttendanceExportBusy(true);const file=await branchAttendanceExport(attendance,attendanceExport.selected),url=URL.createObjectURL(new Blob([file.buffer],{type:file.mime}));const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);setAttendanceExport(null);flash('Đã xuất chấm công các chi nhánh được chọn.')}catch(e){setError('Xuất chấm công thất bại: '+e.message)}finally{setAttendanceExportBusy(false)}}
